import re
from datetime import datetime
from typing import Any, Dict, List

_DATE_FORMATS = ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_ANGLE_RE = re.compile(r"<([^<>]*)>")
_EXT_RE = re.compile(r"ext|x|#", re.IGNORECASE)
_NON_DIGIT_RE = re.compile(r"[^0-9]")
_FIVE_DIGITS_RE = re.compile(r"^[0-9]{5}$")
_FOUR_DIGITS_RE = re.compile(r"^[0-9]{4}$")
_TAG_SPLIT_RE = re.compile(r"[;,]")


def _norm_email(raw: str) -> str:
    """Rule 1: returns the normalized email (not yet validity-checked)."""
    s = raw or ""
    m = _ANGLE_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.split("+", 1)[0].replace(".", "")
            s = local + "@gmail.com"
    return s


def _email_valid(email: str) -> bool:
    """Rule 2."""
    if email.count("@") != 1:
        return False
    local, domain = email.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _norm_phone(raw: str) -> str:
    """Rule 3: returns 10 digits if valid, else ''."""
    s = raw or ""
    m = _EXT_RE.search(s)
    if m:
        s = s[: m.start()]
    digits = _NON_DIGIT_RE.sub("", s)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _norm_zip(raw: str) -> str:
    """Rule 4."""
    z = (raw or "").strip()
    if "-" in z:
        z = z.split("-", 1)[0].strip()
    if _FOUR_DIGITS_RE.match(z):
        z = "0" + z
    return z if _FIVE_DIGITS_RE.match(z) else ""


def _norm_name(raw: str) -> str:
    """Rule 5."""
    s = (raw or "").strip()
    if s and (s.isupper() or s.islower()):
        return s.title()
    return s


def _parse_updated(raw: str) -> datetime:
    """Rule 6. Unparseable values sort as the oldest possible date."""
    s = (raw or "").strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    return datetime.min


def _opted_out(raw: str) -> bool:
    """Rule 7."""
    return (raw or "").strip().lower() in _OPT_OUT_VALUES


def _norm_tags(raw: str) -> List[str]:
    """Rule 8."""
    return [t.strip().lower() for t in _TAG_SPLIT_RE.split(raw or "") if t.strip()]


def dedupe_contacts(rows: List[Dict[str, str]]) -> List[Dict[str, str]]:
    # --- Normalize every row (rules 1-9) ---------------------------------
    recs: List[Dict[str, Any]] = []
    for idx, row in enumerate(rows):
        email = _norm_email(row.get("email", ""))
        if not _email_valid(email):
            email = ""
        phone = _norm_phone(row.get("phone", ""))
        if not email and not phone:
            continue  # rule 9
        recs.append(
            {
                "idx": idx,
                "first_name": _norm_name(row.get("first_name", "")),
                "last_name": _norm_name(row.get("last_name", "")),
                "email": email,
                "phone": phone,
                "zip": _norm_zip(row.get("zip", "")),
                "source": (row.get("source", "") or "").strip().lower(),
                "tags": _norm_tags(row.get("tags", "")),
                "opted_out": _opted_out(row.get("opted_out", "")),
                "updated": _parse_updated(row.get("updated", "")),
            }
        )

    # --- Union-find for transitive matching (rule 10) --------------------
    parent = list(range(len(recs)))

    def find(i: int) -> int:
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra != rb:
            # keep the smaller index as root so groups track their earliest row
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    by_email: Dict[str, int] = {}
    by_phone_last: Dict[tuple, int] = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in by_email:
                union(i, by_email[r["email"]])
            else:
                by_email[r["email"]] = i
        if r["phone"] and r["last_name"]:
            key = (r["phone"], r["last_name"].lower())
            if key in by_phone_last:
                union(i, by_phone_last[key])
            else:
                by_phone_last[key] = i

    groups: Dict[int, List[Dict[str, Any]]] = {}
    for i, r in enumerate(recs):
        groups.setdefault(find(i), []).append(r)

    # --- Build one output row per person (rules 11-12) -------------------
    def pick(group: List[Dict[str, Any]], field: str) -> str:
        candidates = [r for r in group if r[field]]
        if not candidates:
            return ""
        best = max(
            candidates,
            key=lambda r: (r["source"] == "manual", r["updated"], -r["idx"]),
        )
        return best[field]

    out: List[Dict[str, str]] = []
    # groups keyed by root; root is always the group's earliest surviving row
    for root in sorted(groups, key=lambda k: min(r["idx"] for r in groups[k])):
        group = groups[root]
        tags = sorted({t for r in group for t in r["tags"]})
        out.append(
            {
                "first_name": pick(group, "first_name"),
                "last_name": pick(group, "last_name"),
                "email": pick(group, "email"),
                "phone": pick(group, "phone"),
                "zip": pick(group, "zip"),
                "source": pick(group, "source"),
                "tags": ";".join(tags),
                "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
                "updated": max(r["updated"] for r in group).strftime("%Y-%m-%d"),
            }
        )
    return out
```

A few notes on behavior worth knowing before tomorrow's send:

- **Opt-outs are flagged, not removed.** Per rule 11 the function outputs merged people with `opted_out` = `"Y"` or `"N"`. Make sure your send step filters on `opted_out == "N"`; since one opt-out anywhere in a group marks the whole person, this is the safe direction.
- **Rule 9 drops rows with neither valid email nor valid phone**, so those contacts silently disappear. If you want to audit what gets dropped, it's a two-line change to collect them.
- **`updated` is assumed to always parse.** Per the spec it's never empty, but if a stray value sneaks through, it's treated as the oldest possible date rather than crashing the run (it won't win any tie-breaks, and a group made up only of such rows would show `updated` as `0001-01-01`, which is easy to spot).
- **Phone extension markers:** any `x`, `ext`, or `#` cuts the phone off there, so a phone written with a stray letter `x` elsewhere would be truncated. That matches the rule as written; just flagging it.
